1	import {
2	  createCipheriv,
3	  createDecipheriv,
4	  createHash,
5	  createHmac,
6	  randomBytes,
7	  randomInt
8	} from "node:crypto";
9	import { readFileSync, statSync } from "node:fs";
10	import { chmod, mkdir, open } from "node:fs/promises";
11	import { join } from "node:path";
12	import { argon2Verify, argon2id } from "hash-wasm";
13	
14	const KEY_BYTES = 32;
15	const NONCE_BYTES = 12;
16	const AUTH_TAG_BYTES = 16;
17	
18	export type AeadAad = readonly [
19	  schema: string,
20	  table: string,
21	  primaryKey: string,
22	  runId: string,
23	  ownerUserId: string,
24	  keyId: string,
25	  envelopeVersion: "1"
26	];
27	
28	export interface CryptoEnvelope {
29	  readonly v: 1;
30	  readonly keyId: string;
31	  readonly nonce: string;
32	  readonly ct: string;
33	  readonly tag: string;
34	}
35	
36	export class CryptoError extends Error {
37	  constructor(readonly code: string, message: string) {
38	    super(message);
39	    this.name = "CryptoError";
40	  }
41	}
42	
43	export class CryptoAuthenticationError extends CryptoError {
44	  constructor() {
45	    super("CRYPTO_AUTHENTICATION_FAILED", "CRYPTO_AUTHENTICATION_FAILED");
46	    this.name = "CryptoAuthenticationError";
47	  }
48	}
49	
50	export class KekUnresolvedError extends CryptoError {
51	  constructor() {
52	    super("KEK_UNRESOLVED", "KEK_UNRESOLVED");
53	    this.name = "KekUnresolvedError";
54	  }
55	}
56	
57	class CryptoInputError extends CryptoError {
58	  constructor(code:
59	    | "CRYPTO_AAD_INVALID"
60	    | "CRYPTO_AUDIT_CHAIN_INVALID"
61	    | "CRYPTO_CANONICAL_VALUE_INVALID"
62	    | "CRYPTO_EMAIL_INVALID"
63	    | "CRYPTO_KEY_INVALID") {
64	    super(code, code);
65	    this.name = "CryptoInputError";
66	  }
67	}
