69	declare const kekHandleBrand: unique symbol;
70	export interface KekHandle {
71	  readonly [kekHandleBrand]: true;
72	}
73	
74	const kekMaterials = new WeakMap<KekHandle, Buffer>();
75	
76	function copyKey(material: Uint8Array): Buffer {
77	  const key = Buffer.from(material);
78	  if (key.byteLength !== KEY_BYTES) {
79	    key.fill(0);
80	    throw new CryptoInputError("CRYPTO_KEY_INVALID");
81	  }
82	  return key;
83	}
84	
85	function makeKekHandle(material: Uint8Array): KekHandle {
86	  const key = copyKey(material);
87	  const handle = Object.freeze(Object.create(null)) as KekHandle;
88	  kekMaterials.set(handle, key);
89	  return handle;
90	}
91	
92	function readKek(handle: KekHandle): Buffer {
93	  const material = kekMaterials.get(handle);
94	  if (material === undefined) throw new KekUnresolvedError();
95	  return Buffer.from(material);
96	}
97	
98	function validateAad(aad: AeadAad): void {
99	  if (!Array.isArray(aad) || aad.length !== 7 || aad[6] !== "1"
100	    || aad.some((component) => typeof component !== "string" || component.length === 0)) {
101	    throw new CryptoInputError("CRYPTO_AAD_INVALID");
102	  }
103	}
104	
105	function authenticatedData(envelopeVersion: 1, envelopeKeyId: string, aad: AeadAad): Buffer {
106	  validateAad(aad);
107	  return Buffer.from(JSON.stringify([envelopeVersion, envelopeKeyId, aad]), "utf8");
108	}
109	
110	function decodeBase64(value: string): Buffer {
111	  if (typeof value !== "string") throw new CryptoAuthenticationError();
112	  const decoded = Buffer.from(value, "base64");
113	  if (decoded.toString("base64") !== value) throw new CryptoAuthenticationError();
114	  return decoded;
115	}
116	
117	export function generateDek(): Buffer {
118	  return randomBytes(KEY_BYTES);
119	}
120	
121	export function encrypt(dek: Uint8Array, plaintext: Uint8Array, aad: AeadAad): CryptoEnvelope {
122	  const key = copyKey(dek);
123	  try {
124	    validateAad(aad);
125	    const envelopeKeyId = aad[5];
126	    const nonce = randomBytes(NONCE_BYTES);
127	    const cipher = createCipheriv("aes-256-gcm", key, nonce, { authTagLength: AUTH_TAG_BYTES });
128	    cipher.setAAD(authenticatedData(1, envelopeKeyId, aad));
129	    const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
130	    const tag = cipher.getAuthTag();
131	
132	    // Accepted residual: AES-GCM-SIV/XChaCha20 would add nonce-misuse resistance.
133	    // Until that upgrade, every call draws a fresh 96-bit nonce and per-DEK use
134	    // must remain well below the nonce birthday bound.
135	    return Object.freeze({
136	      v: 1,
137	      keyId: envelopeKeyId,
138	      nonce: nonce.toString("base64"),
139	      ct: ciphertext.toString("base64"),
140	      tag: tag.toString("base64")
141	    });
142	  } finally {
143	    key.fill(0);
144	  }
145	}
146	
147	export function decrypt(dek: Uint8Array, envelope: CryptoEnvelope, aad: AeadAad): Buffer {
148	  let key: Buffer | undefined;
149	  try {
150	    key = copyKey(dek);
151	    validateAad(aad);
152	    if (envelope.v !== 1 || envelope.keyId !== aad[5]) {
153	      throw new CryptoAuthenticationError();
154	    }
155	    const nonce = decodeBase64(envelope.nonce);
156	    const ciphertext = decodeBase64(envelope.ct);
157	    const tag = decodeBase64(envelope.tag);
158	    if (nonce.byteLength !== NONCE_BYTES || tag.byteLength !== AUTH_TAG_BYTES) {
159	      throw new CryptoAuthenticationError();
160	    }
161	    const decipher = createDecipheriv("aes-256-gcm", key, nonce, { authTagLength: AUTH_TAG_BYTES });
162	    decipher.setAAD(authenticatedData(envelope.v, envelope.keyId, aad));
163	    decipher.setAuthTag(tag);
164	    return Buffer.concat([decipher.update(ciphertext), decipher.final()]);
165	  } catch (error) {
166	    if (error instanceof CryptoInputError && error.code === "CRYPTO_KEY_INVALID") throw error;
167	    if (error instanceof CryptoAuthenticationError) throw error;
168	    throw new CryptoAuthenticationError();
169	  } finally {
170	    key?.fill(0);
171	  }
172	}
173	
174	export function loadKek(pathOrBuffer: string | Uint8Array): KekHandle {
175	  try {
176	    if (typeof pathOrBuffer !== "string") return makeKekHandle(pathOrBuffer);
177	    const metadata = statSync(pathOrBuffer);
178	    if (!metadata.isFile() || (metadata.mode & 0o777) !== 0o600) {
179	      throw new KekUnresolvedError();
180	    }
181	    return makeKekHandle(readFileSync(pathOrBuffer));
182	  } catch (error) {
183	    if (error instanceof KekUnresolvedError) throw error;
184	    throw new KekUnresolvedError();
185	  }
186	}
187	
188	export function loadSecretKey(path: string): Buffer {
189	  try {
190	    const metadata = statSync(path);
191	    if (!metadata.isFile() || (metadata.mode & 0o777) !== 0o600) {
192	      throw new KekUnresolvedError();
193	    }
194	    return copyKey(readFileSync(path));
195	  } catch (error) {
196	    if (error instanceof KekUnresolvedError || error instanceof CryptoInputError) throw error;
197	    throw new KekUnresolvedError();
198	  }
199	}
200	
201	export function wrapDek(kek: KekHandle, dek: Uint8Array, aad: AeadAad): CryptoEnvelope {
202	  const key = readKek(kek);
203	  try {
204	    return encrypt(key, dek, aad);
205	  } finally {
206	    key.fill(0);
207	  }
208	}
209	
210	export function unwrapDek(kek: KekHandle, envelope: CryptoEnvelope, aad: AeadAad): Buffer {
211	  const key = readKek(kek);
212	  try {
213	    const dek = decrypt(key, envelope, aad);
214	    if (dek.byteLength !== KEY_BYTES) {
215	      dek.fill(0);
216	      throw new CryptoAuthenticationError();
217	    }
218	    return dek;
219	  } finally {
220	    key.fill(0);
221	  }
222	}
