224	export type AuditEventPayload = Readonly<Record<string, unknown>>;
225	
226	export type ChainedAuditEvent<T extends AuditEventPayload = AuditEventPayload> = Readonly<T & {
227	  readonly prevHash: string | null;
228	  readonly thisHash: string;
229	}>;
230	
231	function canonicalJson(value: unknown): string {
232	  if (value === null) return "null";
233	  if (typeof value === "string" || typeof value === "boolean") return JSON.stringify(value);
234	  if (typeof value === "number") {
235	    if (!Number.isFinite(value)) throw new CryptoInputError("CRYPTO_CANONICAL_VALUE_INVALID");
236	    return JSON.stringify(value);
237	  }
238	  if (Buffer.isBuffer(value) || value instanceof Uint8Array) {
239	    return canonicalJson({ $bytes: Buffer.from(value).toString("base64") });
240	  }
241	  if (value instanceof Date) return JSON.stringify(value.toISOString());
242	  if (Array.isArray(value)) return `[${value.map((item) => canonicalJson(item)).join(",")}]`;
243	  if (typeof value === "object") {
244	    const prototype = Object.getPrototypeOf(value);
245	    if (prototype !== Object.prototype && prototype !== null) {
246	      throw new CryptoInputError("CRYPTO_CANONICAL_VALUE_INVALID");
247	    }
248	    const entries = Object.entries(value as Readonly<Record<string, unknown>>)
249	      .sort(([left], [right]) => left.localeCompare(right));
250	    return `{${entries.map(([key, item]) =>
251	      `${JSON.stringify(key)}:${canonicalJson(item)}`).join(",")}}`;
252	  }
253	  throw new CryptoInputError("CRYPTO_CANONICAL_VALUE_INVALID");
254	}
255	
256	function validateAuditHash(hash: string): void {
257	  if (!/^[0-9a-f]{64}$/.test(hash)) {
258	    throw new CryptoInputError("CRYPTO_AUDIT_CHAIN_INVALID");
259	  }
260	}
261	
262	function auditHash(prevHash: string | null, payload: AuditEventPayload): string {
263	  if (prevHash !== null) validateAuditHash(prevHash);
264	  if (Object.hasOwn(payload, "prevHash") || Object.hasOwn(payload, "thisHash")) {
265	    throw new CryptoInputError("CRYPTO_AUDIT_CHAIN_INVALID");
266	  }
267	  const digest = createHash("sha256");
268	  if (prevHash !== null) digest.update(Buffer.from(prevHash, "hex"));
269	  digest.update(canonicalJson(payload), "utf8");
270	  return digest.digest("hex");
271	}
272	
273	/**
274	 * Appends one logical audit row with this_hash = H(prev_hash || canonical(payload)).
275	 * The payload deliberately excludes both hash columns; prev_hash comes solely
276	 * from the verified predecessor, so callers cannot construct a fork by accident.
277	 */
278	export function appendAuditEvent<T extends AuditEventPayload>(
279	  previous: ChainedAuditEvent | string | null,
280	  payload: T
281	): ChainedAuditEvent<T> {
282	  const prevHash = typeof previous === "string" ? previous : previous?.thisHash ?? null;
283	  const thisHash = auditHash(prevHash, payload);
284	  return Object.freeze({ ...payload, prevHash, thisHash });
285	}
286	
287	/**
288	 * Verifies genesis, every predecessor link, and every row digest. Supplying an
289	 * externally retained expected head additionally detects tail truncation.
290	 */
291	export function verifyChain(
292	  chain: readonly ChainedAuditEvent[],
293	  expectedHeadHash?: string
294	): boolean {
295	  try {
296	    let expectedPrev: string | null = null;
297	    for (const event of chain) {
298	      if (event.prevHash !== expectedPrev) return false;
299	      validateAuditHash(event.thisHash);
300	      const { prevHash: _prevHash, thisHash: _thisHash, ...payload } = event;
301	      if (auditHash(expectedPrev, payload) !== event.thisHash) return false;
302	      expectedPrev = event.thisHash;
303	    }
304	    if (expectedHeadHash !== undefined) {
305	      validateAuditHash(expectedHeadHash);
306	      return expectedPrev === expectedHeadHash;
307	    }
308	    return true;
309	  } catch {
310	    return false;
311	  }
312	}
313	
314	export function normalizeEmailForBlindIndex(email: string): string {
315	  const normalized = email.normalize("NFKC").trim().toLowerCase();
316	  if (normalized.length === 0 || !normalized.includes("@")) {
317	    throw new CryptoInputError("CRYPTO_EMAIL_INVALID");
318	  }
319	  return normalized;
320	}
321	
322	/**
323	 * Deterministic login lookup only. The key is global, separate from the KEK,
324	 * and independently rotatable. If an attacker compromises both the database
325	 * and this key, email's small domain permits offline enumeration; callers must
326	 * never treat the blind index as encryption or expose the key to the database.
327	 */
328	export function createEmailBlindIndex(key: Uint8Array, email: string): Buffer {
329	  const material = copyKey(key);
330	  try {
331	    return createHmac("sha256", material)
332	      .update(normalizeEmailForBlindIndex(email), "utf8")
333	      .digest();
334	  } finally {
335	    material.fill(0);
336	  }
337	}
338	
339	export const emailBlindIndex = createEmailBlindIndex;
340	
341	export interface Argon2idParameters {
342	  readonly memoryCostKiB: number;
343	  readonly timeCost: number;
344	  readonly parallelism: number;
345	  readonly hashLength: number;
346	}
347	
348	export interface AuditSourceIpKdfParameters {
349	  readonly algorithm: "argon2id";
350	  readonly memoryCostKiB: number;
351	  readonly iterations: number;
352	  readonly parallelism: number;
353	  readonly hashLength: 32;
354	}
355	
356	const AUDIT_SOURCE_IP_KDF_DOMAIN = "debateai:audit-source-ip:v1\0";
357	const AUDIT_USER_AGENT_KDF_DOMAIN = "debateai:audit-user-agent:v1\0";
358	
359	async function hashAuditContextValue(
360	  value: string,
361	  salt: Uint8Array,
362	  parameters: AuditSourceIpKdfParameters,
363	  domain: string
364	): Promise<string> {
365	  if (value.length === 0 || salt.byteLength < 32 || parameters.algorithm !== "argon2id"
366	    || !Number.isInteger(parameters.memoryCostKiB) || parameters.memoryCostKiB < 19_456
367	    || !Number.isInteger(parameters.iterations) || parameters.iterations < 2
368	    || !Number.isInteger(parameters.parallelism) || parameters.parallelism < 1
369	    || parameters.hashLength !== 32) {
370	    throw new CryptoInputError("CRYPTO_KEY_INVALID");
371	  }
372	  return argon2id({
373	    password: `${domain}${value}`,
374	    salt,
375	    memorySize: parameters.memoryCostKiB,
376	    iterations: parameters.iterations,
377	    parallelism: parameters.parallelism,
378	    hashLength: parameters.hashLength,
379	    outputType: "hex"
380	  });
381	}
382	
383	export async function hashAuditSourceIp(
384	  sourceIp: string,
385	  salt: Uint8Array,
386	  parameters: AuditSourceIpKdfParameters
387	): Promise<string> {
388	  return hashAuditContextValue(sourceIp, salt, parameters, AUDIT_SOURCE_IP_KDF_DOMAIN);
389	}
390	
391	export async function hashAuditUserAgent(
392	  userAgent: string,
393	  salt: Uint8Array,
394	  parameters: AuditSourceIpKdfParameters
395	): Promise<string> {
396	  return hashAuditContextValue(userAgent, salt, parameters, AUDIT_USER_AGENT_KDF_DOMAIN);
397	}
398	
399	export async function hashPassword(password: string, parameters: Argon2idParameters): Promise<string> {
400	  if (typeof password !== "string" || password.length === 0
401	    || !Number.isInteger(parameters.memoryCostKiB) || parameters.memoryCostKiB < 19_456
402	    || !Number.isInteger(parameters.timeCost) || parameters.timeCost < 2
403	    || !Number.isInteger(parameters.parallelism) || parameters.parallelism < 1
404	    || !Number.isInteger(parameters.hashLength) || parameters.hashLength < 32) {
405	    throw new CryptoInputError("CRYPTO_KEY_INVALID");
406	  }
407	  return argon2id({
408	    password,
409	    salt: randomBytes(16),
410	    memorySize: parameters.memoryCostKiB,
411	    iterations: parameters.timeCost,
412	    parallelism: parameters.parallelism,
413	    hashLength: parameters.hashLength,
414	    outputType: "encoded"
415	  });
416	}
417	
418	export async function verifyPassword(encodedHash: string, password: string): Promise<boolean> {
419	  if (!encodedHash.startsWith("$argon2id$")) return false;
420	  try {
421	    return await argon2Verify({ password, hash: encodedHash });
422	  } catch {
423	    return false;
424	  }
425	}
426	
427	export function generateVerificationToken(): string {
428	  return randomBytes(32).toString("base64url");
429	}
430	
431	export function hashVerificationToken(token: string): string {
432	  if (typeof token !== "string" || token.length < 32) {
433	    throw new CryptoInputError("CRYPTO_KEY_INVALID");
434	  }
435	  return `sha256:${createHash("sha256").update(token, "utf8").digest("hex")}`;
436	}
437	
438	const PSEUDONYM_ADJECTIVES = Object.freeze([
439	  "amber", "brisk", "calm", "clear", "cobalt", "coral", "crisp", "daring",
440	  "ember", "gentle", "golden", "honest", "indigo", "lucid", "mellow", "nimble",
441	  "open", "patient", "quiet", "rapid", "silver", "steady", "verdant", "vivid"
442	]);
443	const PSEUDONYM_NOUNS = Object.freeze([
444	  "badger", "cedar", "comet", "dolphin", "falcon", "forest", "harbor", "heron",
445	  "island", "lantern", "maple", "meadow", "otter", "pebble", "quartz", "raven",
446	  "river", "sparrow", "summit", "thistle", "tiger", "willow", "wren", "zephyr"
447	]);
448	
449	export function generatePseudonym(): string {
450	  const adjective = PSEUDONYM_ADJECTIVES[randomInt(PSEUDONYM_ADJECTIVES.length)]!;
451	  const noun = PSEUDONYM_NOUNS[randomInt(PSEUDONYM_NOUNS.length)]!;
452	  return `${adjective}-${noun}-${randomBytes(3).toString("hex")}`;
453	}
454	
455	export interface UserDekStore {
456	  store(userId: string, dek: Uint8Array): Promise<void>;
457	}
458	
459	export class FileUserDekStore implements UserDekStore {
460	  constructor(
461	    private readonly root: string,
462	    private readonly kek: KekHandle
463	  ) {
464	    if (root.trim() === "") throw new TypeError("USER_DEK_STORE_PATH_REQUIRED");
465	  }
466	
467	  async store(userId: string, dek: Uint8Array): Promise<void> {
468	    if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(userId)) {
469	      throw new TypeError("USER_DEK_STORE_USER_ID_INVALID");
470	    }
471	    const aad = [
472	      "secret-store", "user-dek", userId, "run:none", userId,
473	      `user-dek:${userId}`, "1"
474	    ] as const;
475	    const envelope = wrapDek(this.kek, dek, aad);
476	    const users = join(this.root, "users");
477	    const directory = join(users, userId);
478	    await mkdir(this.root, { recursive: true, mode: 0o700 });
479	    await chmod(this.root, 0o700);
480	    await mkdir(users, { recursive: true, mode: 0o700 });
481	    await chmod(users, 0o700);
482	    await mkdir(directory, { recursive: false, mode: 0o700 });
483	    const location = join(directory, "dek.v1.json");
484	    const file = await open(location, "wx", 0o600);
485	    try {
486	      await file.writeFile(JSON.stringify({
487	        version: 1,
488	        user_id: userId,
489	        key_id: envelope.keyId,
490	        wrapped_dek: envelope
491	      }), "utf8");
492	    } finally {
493	      await file.close();
494	    }
495	  }
496	}
