  // never turned between dispatch and settlement.
  const controlHash = await controlPending;
  const controlMs = performance.now() - controlStart;
  const controlAfter = snapshot();

  // 3b. One single direct audit-IP KDF, measured alone.
  const auditSalt = randomBytes(32);
  const ipBefore = snapshot();
  const ipStart = performance.now();
  const ipDigest = await directHashAuditContext("203.0.113.7", auditSalt, AUDIT_SOURCE_IP_KDF_DOMAIN);
  const ipMs = performance.now() - ipStart;
  const ipAfter = snapshot();

  // 3c. One single direct audit-UA KDF, measured alone.
  const uaBefore = snapshot();
  const uaStart = performance.now();
  const uaDigest = await directHashAuditContext(
    "Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_7) T1RedRepro/1.0",
    auditSalt,
    AUDIT_USER_AGENT_KDF_DOMAIN
  );
  const uaMs = performance.now() - uaStart;
  const uaAfter = snapshot();

  // 4. The real registration-shaped batch: eight password KDFs, each with its
  //    audit IP + UA derivations, exactly as the current request path runs them.
  const batchGapMark = intervalGaps.length;
  const batchBefore = snapshot();
  const batchStart = performance.now();
  const perJob = [];
  for (let index = 0; index < PASSWORD_JOBS; index += 1) {
    const jobBefore = snapshot();
    const jobStart = performance.now();
    const encoded = await directHashPassword(`red-repro-password-${index}-${randomBytes(8).toString("hex")}`);
    const passwordMs = performance.now() - jobStart;
    const ipAt = performance.now();
    await directHashAuditContext(`198.51.100.${index}`, auditSalt, AUDIT_SOURCE_IP_KDF_DOMAIN);
    const jobIpMs = performance.now() - ipAt;
    const uaAt = performance.now();
    await directHashAuditContext(`T1RedRepro/${index}`, auditSalt, AUDIT_USER_AGENT_KDF_DOMAIN);
    const jobUaMs = performance.now() - uaAt;
    const jobAfter = snapshot();
    perJob.push({
      index,
      passwordMs: Number(passwordMs.toFixed(3)),
      auditIpMs: Number(jobIpMs.toFixed(3)),
      auditUaMs: Number(jobUaMs.toFixed(3)),
      totalMs: Number((performance.now() - jobStart).toFixed(3)),
      intervalTicksDuringJob: jobAfter.interval - jobBefore.interval,
      immediateTicksDuringJob: jobAfter.immediate - jobBefore.immediate,
      encodedPrefix: encoded.slice(0, 10)
    });
  }
  const batchMs = performance.now() - batchStart;
  const batchAfter = snapshot();
  const batchGaps = intervalGaps.slice(batchGapMark);

  stopProbes();

  const report = {
    kind: "T1-RED-DIRECT-ARGON2",
    node: process.version,
    platform: `${process.platform}-${process.arch}`,
    hashWasm: "4.12.0",
    policy: { password: PASSWORD_PARAMS, audit: AUDIT_PARAMS },
    warmupMs: Number(warmMs.toFixed(3)),
    idleBaseline: {
      windowMs: 200,
      intervalTicks: idleBaseline.interval,
      immediateTicks: idleBaseline.immediate,
      probesAliveWhileIdle: idleBaseline.interval > 0 && idleBaseline.immediate > 0
    },
    positiveControlPasswordKdf: {
      wallMs: Number(controlMs.toFixed(3)),
      intervalTicksInFlight: controlAfter.interval - controlBefore.interval,
      immediateTicksInFlight: controlAfter.immediate - controlBefore.immediate,
      encodedPrefix: controlHash.slice(0, 10)
    },
    directAuditIpKdf: {
      wallMs: Number(ipMs.toFixed(3)),
      intervalTicksInFlight: ipAfter.interval - ipBefore.interval,
      immediateTicksInFlight: uaBefore.immediate - ipBefore.immediate,
      digestLength: ipDigest.length
    },
    directAuditUaKdf: {
      wallMs: Number(uaMs.toFixed(3)),
      intervalTicksInFlight: uaAfter.interval - uaBefore.interval,
      immediateTicksInFlight: uaAfter.immediate - uaBefore.immediate,
      digestLength: uaDigest.length
    },
    eightPasswordBatch: {
      passwordJobs: PASSWORD_JOBS,
      auditKdfsPerJob: 2,
      wallMs: Number(batchMs.toFixed(3)),
      intervalTicksDuringBatch: batchAfter.interval - batchBefore.interval,
      immediateTicksDuringBatch: batchAfter.immediate - batchBefore.immediate,
      maxEventLoopGapMs: Number(Math.max(0, ...batchGaps).toFixed(3)),
      p99EventLoopGapMs: Number(percentile(batchGaps, 99).toFixed(3)),
      perJob
    },
    maxEventLoopGapMsOverall: Number(maxIntervalGapMs.toFixed(3)),
    verdict: {
      // RED is proven when a single direct password KDF admits ZERO in-flight
      // heartbeat progress on both probes, and the batch exhibits a
      // multi-hundred-millisecond event-loop gap.
      positiveControlZeroInFlightHeartbeats:
        (controlAfter.interval - controlBefore.interval) === 0
        && (controlAfter.immediate - controlBefore.immediate) === 0,
      substantiveFreeze: maxIntervalGapMs >= 50
    }
  };

  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
  process.exitCode = report.verdict.positiveControlZeroInFlightHeartbeats
    && report.verdict.substantiveFreeze
    && report.idleBaseline.probesAliveWhileIdle ? 0 : 3;
}

main().catch((error) => {
  stopProbes();
  process.stdout.write(`${JSON.stringify({ kind: "T1-RED-DIRECT-ARGON2", error: String(error && error.message) })}\n`);
  process.exitCode = 4;
});

