371	      `, [input.userId]);
372	      const user = await client.query<{ audit_token: string }>(`
373	        SELECT audit_token FROM identity."user" WHERE user_id=$1 FOR UPDATE
374	      `, [input.userId]);
375	      if (user.rows[0] === undefined) throw new Error("IDENTITY_USER_NOT_FOUND");
376	      await this.appendAudit(client, {
377	        actorToken: user.rows[0].audit_token,
378	        eventType: "identity.registration.duplicate_postwork",
379	        targetType: "identity.channel_binding",
380	        occurredAt: input.occurredAt,
381	        source: input.source,
382	        decision: "DENY",
383	        success: false,
384	        justification: "REGISTRATION_ADDRESS_UNAVAILABLE"
385	      });
386	    });
387	  }
388	
389	  async consumeVerification(input: {
390	    readonly tokenHash: string;
391	    readonly occurredAt: Date;
392	    readonly source: AuthSourceContext;
393	  }): Promise<boolean> {
394	    return this.transaction(async (client) => {
395	      // Explicit sequential row locking in the account-local order
396	      // channel -> user -> credential. A multi-relation `FOR UPDATE OF` list is
397	      // not a portable acquisition-order contract, so each row is locked by its
398	      // own statement and every decision is re-derived from the locked rows.
399	      //
400	      // Step 1: locate the candidate credential's parent channel. This is only a
401	      // locator; it takes no row lock and is never authorization.
402	      const located = await client.query<{ channel_binding_id: string }>(`
403	        SELECT c.channel_binding_id
404	        FROM identity.verification_token_credential token
405	        JOIN identity.channel_binding c ON c.channel_binding_id=token.channel_binding_id
406	        WHERE token.token_hash=$1 AND c.channel_type='email'
407	      `, [input.tokenHash]);
408	      const locatedChannelBindingId = located.rows[0]?.channel_binding_id;
409	      // Step 2: lock that exact email channel row and read the authoritative
410	      // user_id back off the locked row.
411	      const channel = locatedChannelBindingId === undefined ? undefined : (
412	        await client.query<{ channel_binding_id: string; user_id: string }>(`
413	          SELECT channel_binding_id,user_id FROM identity.channel_binding
414	          WHERE channel_binding_id=$1 AND channel_type='email'
415	          FOR UPDATE
416	        `, [locatedChannelBindingId])
417	      ).rows[0];
418	      // Step 3: lock that exact user row and read its actor token and state.
419	      const user = channel === undefined ? undefined : (
420	        await client.query<{ audit_token: string; state: string }>(`
421	          SELECT audit_token,state FROM identity."user" WHERE user_id=$1 FOR UPDATE
422	        `, [channel.user_id])
423	      ).rows[0];
424	      // Step 4: only now lock and re-read the requested credential, restricted
425	      // to both the token hash and the locked channel binding.
426	      const credential = channel === undefined || user === undefined ? undefined : (
427	        await client.query<{ expires_at: Date; consumed_at: Date | null }>(`
428	          SELECT expires_at,consumed_at FROM identity.verification_token_credential
429	          WHERE token_hash=$1 AND channel_binding_id=$2
430	          FOR UPDATE
431	        `, [input.tokenHash, channel.channel_binding_id])
432	      ).rows[0];
433	      // Step 5: validity comes only from the locked, revalidated rows. Missing,
434	      // moved, pruned, consumed, expired, wrong-channel or non-pending is the
435	      // existing typed invalid-token outcome.
436	      const valid = channel !== undefined
437	        && user !== undefined
438	        && credential !== undefined
439	        && credential.consumed_at === null
440	        && credential.expires_at.getTime() >= input.occurredAt.getTime()
441	        && user.state === "pending_verification";
442	      const actorToken = user?.audit_token ?? randomUUID();
443	      if (channel !== undefined && valid) {
444	        await client.query(`
445	          UPDATE identity.verification_token_credential SET consumed_at=$2
446	          WHERE channel_binding_id=$1 AND consumed_at IS NULL
447	        `, [channel.channel_binding_id, input.occurredAt]);
448	        await client.query(`
449	          UPDATE identity.channel_binding
450	          SET state='verified',verified_at=$2,verification_consumed_at=$2,
451	            delivery_error=NULL
452	          WHERE channel_binding_id=$1
453	        `, [channel.channel_binding_id, input.occurredAt]);
454	        await client.query(`UPDATE identity."user" SET state='active' WHERE user_id=$1`, [channel.user_id]);
455	      }
456	      await this.appendAudit(client, {
457	        actorToken,
458	        eventType: "identity.verification.consumed",
459	        targetType: "identity.channel_binding",
460	        occurredAt: input.occurredAt,
461	        source: input.source,
462	        decision: valid ? "ALLOW" : "DENY",
463	        success: valid,
464	        justification: valid ? null : "VERIFICATION_TOKEN_INVALID"
465	      });
466	      return valid;
467	    });
468	  }
469	
470	  async prepareVerificationResend(input: {
471	    readonly emailBlindIndex: Buffer;
472	    readonly tokenHash: string;
473	    readonly expiresAt: Date;
474	    readonly occurredAt: Date;
475	    readonly cooldownMs: number;
476	    readonly source: AuthSourceContext;
477	  }): Promise<ResendPreparation> {
478	    return this.transaction(async (client) => {
479	      const found = await client.query<{
480	        channel_binding_id: string;
481	        user_id: string;
482	        audit_token: string;
483	        state: string;
484	        verification_last_sent_at: Date | null;
485	      }>(`
486	        SELECT c.channel_binding_id,c.user_id,u.audit_token,u.state,c.verification_last_sent_at
487	        FROM identity."user" u
488	        JOIN identity.channel_binding c ON c.user_id=u.user_id AND c.channel_type='email'
489	        WHERE u.email_blind_index=$1
490	        FOR UPDATE OF c,u
491	      `, [input.emailBlindIndex]);
492	      const row = found.rows[0];
493	      const cooling = row?.verification_last_sent_at !== null && row?.verification_last_sent_at !== undefined
494	        && input.occurredAt.getTime() - row.verification_last_sent_at.getTime() < input.cooldownMs;
495	      const send = row !== undefined && row.state === "pending_verification" && !cooling;
496	      const actorToken = row?.audit_token ?? randomUUID();
497	      if (send) {
498	        await client.query(`
499	          DELETE FROM identity.verification_token_credential
500	          WHERE channel_binding_id=$1 AND expires_at < $2
501	        `, [row.channel_binding_id, input.occurredAt]);
502	        await client.query(`
503	          INSERT INTO identity.verification_token_credential (
504	            token_hash,channel_binding_id,issued_at,expires_at
505	          ) VALUES ($1,$2,$3,$4)
506	        `, [input.tokenHash, row.channel_binding_id, input.occurredAt, input.expiresAt]);
507	        await client.query(`
508	          UPDATE identity.channel_binding
509	          SET verification_token_hash=$2,verification_expires_at=$3,
510	            verification_consumed_at=NULL,verification_last_sent_at=$4,
511	            delivery_status='pending',delivery_error=NULL
512	          WHERE channel_binding_id=$1
513	        `, [row.channel_binding_id, input.tokenHash, input.expiresAt, input.occurredAt]);
514	      }
515	      await this.appendAudit(client, {
516	        actorToken,
517	        eventType: "identity.verification.resend_requested",
518	        targetType: "identity.channel_binding",
519	        occurredAt: input.occurredAt,
520	        source: input.source,
521	        decision: send ? "ALLOW" : "DENY",
522	        success: send,
523	        justification: send ? null : cooling ? "RESEND_COOLDOWN" : "RESEND_NOT_APPLICABLE"
524	      });
525	      return send ? Object.freeze({
526	        status: "send" as const,
527	        userId: row.user_id,
528	        auditToken: row.audit_token,
529	        channelBindingId: row.channel_binding_id
530	      }) : Object.freeze({ status: "ignored" as const });
531	    });
532	  }
533	
534	  async recordRateLimitRefusal(input: {
535	    readonly actorToken: string;
536	    readonly route: "register" | "verify" | "resend";
537	    readonly scope: "ip" | "address";
538	    readonly count: number;
539	    readonly ipCount: number;
540	    readonly addressCount: number;
541	    readonly occurredAt: Date;
