546	      || !Number.isSafeInteger(input.ipCount) || input.ipCount < 0
547	      || !Number.isSafeInteger(input.addressCount) || input.addressCount < 0
548	      || input.ipCount + input.addressCount !== input.count) {
549	      throw new TypeError("RATE_LIMIT_REFUSAL_AGGREGATE_INVALID");
550	    }
551	    await this.transaction((client) => this.appendAudit(client, {
552	      actorToken: input.actorToken,
553	      eventType: "identity.auth.rate_limit_refused",
554	      targetType: `auth.${input.route}`,
555	      occurredAt: input.occurredAt,
556	      source: input.source,
557	      decision: "DENY",
558	      success: false,
559	      justification: `aggregate:route-window;route:${input.route};window:${input.aggregateWindowStartedAt.toISOString()}`
560	        + `;count:${input.count};ip_count:${input.ipCount};address_count:${input.addressCount}`
561	    }));
