565	    readonly correlationId: string;
566	    readonly occurredAt: Date;
567	    readonly source: AuthSourceContext;
568	  }): Promise<void> {
569	    await this.transaction((client) => this.appendAudit(client, {
570	      actorToken: input.correlationId,
571	      eventType: "identity.registration.failed",
572	      targetType: "identity.registration_attempt",
573	      occurredAt: input.occurredAt,
574	      source: input.source,
