// Probe: does hash-wasm argon2 treat a UTF-8 Uint8Array password identically to
// the equivalent JS string? T1 transfers zeroable byte arrays to the worker
// instead of strings, so this MUST be byte-identical or audit golden digests
// and password encodings would change.
import { argon2id, argon2Verify } from "hash-wasm";

const AUDIT_SOURCE_IP_KDF_DOMAIN = "debateai:audit-source-ip:v1\0";
const salt32 = new Uint8Array(32).fill(7);
const salt16 = new Uint8Array(16).fill(3);

const cases = [
  ["ascii", "correct horse battery staple"],
  ["domain+ip (NUL byte inside)", `${AUDIT_SOURCE_IP_KDF_DOMAIN}203.0.113.7`],
  ["non-BMP emoji", "pa$$w🔐rd-\u{1F600}"],
  ["combining marks", "école-café-ﬁ"],
  ["cyrillic+cjk", "Пароль-密码-パスワード"],
  ["lone-ish surrogate pair edge", "\u{10FFFF}tail"]
];

let allEqual = true;
for (const [label, value] of cases) {
  const asString = await argon2id({
    password: value, salt: salt32, memorySize: 19_456, iterations: 2,
    parallelism: 1, hashLength: 32, outputType: "hex"
  });
  const asBytes = await argon2id({
    password: new TextEncoder().encode(value), salt: salt32, memorySize: 19_456,
    iterations: 2, parallelism: 1, hashLength: 32, outputType: "hex"
  });
  const equal = asString === asBytes;
  if (!equal) allEqual = false;
  console.log(`${equal ? "EQUAL  " : "DIFFER "} ${label}`);
  if (!equal) console.log(`   string=${asString}\n   bytes =${asBytes}`);
}

// encoded output + verify round trip, string-hashed vs byte-verified and back.
const pw = "verify-cross-check-🔐";
const encodedFromString = await argon2id({
  password: pw, salt: salt16, memorySize: 65_536, iterations: 3,
  parallelism: 1, hashLength: 32, outputType: "encoded"
});
const encodedFromBytes = await argon2id({
  password: new TextEncoder().encode(pw), salt: salt16, memorySize: 65_536,
  iterations: 3, parallelism: 1, hashLength: 32, outputType: "encoded"
});
const verifyBytesAgainstStringHash = await argon2Verify({
  password: new TextEncoder().encode(pw), hash: encodedFromString
});
const verifyStringAgainstBytesHash = await argon2Verify({ password: pw, hash: encodedFromBytes });
const verifyWrongBytes = await argon2Verify({
  password: new TextEncoder().encode("wrong"), hash: encodedFromString
});

console.log(`encodedEqual=${encodedFromString === encodedFromBytes}`);
console.log(`verifyBytesAgainstStringHash=${verifyBytesAgainstStringHash}`);
console.log(`verifyStringAgainstBytesHash=${verifyStringAgainstBytesHash}`);
console.log(`verifyWrongBytesRejected=${verifyWrongBytes === false}`);

const ok = allEqual && encodedFromString === encodedFromBytes
  && verifyBytesAgainstStringHash && verifyStringAgainstBytesHash && verifyWrongBytes === false;
console.log(`RESULT=${ok ? "BYTE-IDENTICAL" : "NOT-EQUIVALENT"}`);
process.exitCode = ok ? 0 : 1;

