// Probe: can the REAL argon2-worker.ts boot as a strip-only TypeScript worker
// with execArgv: [] (no inherited loader flags), and do real Argon2 work?
import { Worker } from "node:worker_threads";

const workerUrl = new URL(
  "file:///Users/vladmihaimiron/Documents/DebateAIRO/dialectical-engine/packages/crypto/src/argon2-worker.ts"
);

const worker = new Worker(workerUrl, { execArgv: [], name: "argon2-probe" });

const ready = new Promise((resolve, reject) => {
  worker.once("message", (m) => (m?.kind === "ready" ? resolve(m) : reject(new Error(`unexpected ${JSON.stringify(m)}`))));
  worker.once("error", reject);
  worker.once("exit", (code) => reject(new Error(`exited early code=${code}`)));
});

const t0 = performance.now();
await ready;
console.log(`ready in ${(performance.now() - t0).toFixed(1)} ms  threadId=${worker.threadId}`);

function once(request, transfer) {
  return new Promise((resolve, reject) => {
    const onMessage = (m) => {
      if (m?.id !== request.id) return;
      worker.off("message", onMessage);
      resolve(m);
    };
    worker.on("message", onMessage);
    worker.once("error", reject);
    worker.postMessage(request, transfer);
  });
}

