const salt = new Uint8Array(16).fill(3);
const hashed = await once({
  id: "job-1", op: "hash-password", password, salt,
  memoryCostKiB: 65_536, timeCost: 3, parallelism: 1, hashLength: 32
}, [password.buffer, salt.buffer]);
