const rejected = await once({ id: "job-3", op: "verify-password", password: pw3, encodedHash: hashed.digest }, [pw3.buffer]);
console.log("verify-password(wrong) ->", rejected.kind, rejected.matches);

const malformed = new TextEncoder().encode("x");
