  worker.once("message", (m) => (m?.kind === "ready" ? resolve(m) : reject(new Error(`unexpected ${JSON.stringify(m)}`))));
  worker.once("error", reject);
  worker.once("exit", (code) => reject(new Error(`exited early code=${code}`)));
});

