// T1 GREEN measurement child: responsiveness, RSS and close latency for the
// real two-worker pool at the shipped policy values.
const POOL = "/Users/vladmihaimiron/Documents/DebateAIRO/dialectical-engine/packages/crypto/src/argon2-worker-pool.ts";
const { Argon2WorkerPool } = await import(POOL);

const PW = { memoryCostKiB: 65_536, timeCost: 3, parallelism: 1, hashLength: 32 };
const AU = { memoryCostKiB: 19_456, iterations: 2, parallelism: 1, hashLength: 32 };

const pool = new Argon2WorkerPool({ workers: 2 });
await pool.ready();
const rssAfterBoot = process.memoryUsage().rss;

// Warm both real workers so WASM compile is not counted as request latency.
await Promise.all([0, 1].map(() => pool.hashAuditContext(
  new TextEncoder().encode("warm"), new Uint8Array(32).fill(1), AU)));

let ticks = 0, imm = 0, last = performance.now(), maxGap = 0;
const gaps = [];
const iv = setInterval(() => {
  const now = performance.now();
  gaps.push(now - last);
  maxGap = Math.max(maxGap, now - last);
  last = now;
  ticks += 1;
}, 1);
let stop = false;
const pump = () => { if (stop) return; imm += 1; setImmediate(pump); };
setImmediate(pump);

const s1 = { ticks, imm };
const t1 = performance.now();
await pool.hashPassword(new TextEncoder().encode("single"), new Uint8Array(16).fill(2), PW);
const singleMs = performance.now() - t1;
const s1d = { ticks: ticks - s1.ticks, imm: imm - s1.imm };

const s2 = { ticks, imm };
const t2 = performance.now();
await pool.hashAuditContext(
  new TextEncoder().encode("debateai:audit-source-ip:v1�203.0.113.5"),
  new Uint8Array(32).fill(3), AU);
const auditMs = performance.now() - t2;
const s2d = { ticks: ticks - s2.ticks, imm: imm - s2.imm };

const mark = gaps.length;
const b = { ticks, imm };
const tb = performance.now();
await Promise.all(Array.from({ length: 8 }, (_, i) => pool.hashPassword(
  new TextEncoder().encode("batch-" + i), new Uint8Array(16).fill(i + 1), PW)));
const batchMs = performance.now() - tb;
const peakRss = process.memoryUsage().rss;

const bg = gaps.slice(mark).sort((a, b2) => a - b2);
const q = (p) => bg[Math.max(0, Math.ceil(p * bg.length) - 1)] ?? 0;
stop = true;
clearInterval(iv);
const cs = performance.now();
await pool.close();
const closeMs = performance.now() - cs;

console.log(JSON.stringify({
  rssAfterBootMiB: +(rssAfterBoot / 1048576).toFixed(1),
  rssPeakMiB: +(peakRss / 1048576).toFixed(1),
  singlePasswordMs: +singleMs.toFixed(1),
  singleInFlightHeartbeats: s1d,
  singleAuditMs: +auditMs.toFixed(1),
  auditInFlightHeartbeats: s2d,
  batch8Ms: +batchMs.toFixed(1),
  batchTicks: ticks - b.ticks,
  batchImmediates: imm - b.imm,
  p50GapMs: +q(0.5).toFixed(3),
  p99GapMs: +q(0.99).toFixed(3),
  maxGapMs: +maxGap.toFixed(3),
  closeMs: +closeMs.toFixed(1),
  state: pool.stats().state
}, null, 2));

