      async verifyPassword() { calls += 1; return true; },
      async hashAuditContext() { return "0".repeat(64); }
    };
    await verifyPassword(executor, "$argon2id$stored", "pw");
    await verifyPassword(executor, "$argon2id$stored", "pw");
    expect(calls).toBe(2);
  });
});
