// Does the Argon2 worker pool retain memory across sustained use?
//
// This isolates MY component from the rest of the integration suite: one pool,
// many rounds of real work, forced GC between rounds, RSS sampled each round.
// Flat RSS after warm-up => no retention. Linear growth => a real leak.
//
// Run with: node --expose-gc pool-retention.mjs
const POOL = "/Users/vladmihaimiron/Documents/DebateAIRO/dialectical-engine/packages/crypto/src/argon2-worker-pool.ts";
const { Argon2WorkerPool } = await import(POOL);

const PW = { memoryCostKiB: 65_536, timeCost: 3, parallelism: 1, hashLength: 32 };
const AU = { memoryCostKiB: 19_456, iterations: 2, parallelism: 1, hashLength: 32 };

const ROUNDS = 20;
const PER_ROUND = 12;

async function forceGc() {
  for (let i = 0; i < 3; i += 1) {
    globalThis.gc?.();
    await new Promise((r) => setTimeout(r, 20));
  }
}

const pool = new Argon2WorkerPool({ workers: 2 });
await pool.ready();

// Warm both workers so the WASM arenas are already grown before sampling.
await Promise.all([0, 1].map((i) => pool.hashPassword(
  new TextEncoder().encode("warm-" + i), new Uint8Array(16).fill(1), PW)));
await forceGc();

const samples = [];
const restarts = [];
for (let round = 0; round < ROUNDS; round += 1) {
  await Promise.all(Array.from({ length: PER_ROUND }, (_, i) => {
    // Mix both lanes, exactly as the request path does.
    if (i % 3 === 0) {
      return pool.hashAuditContext(
        new TextEncoder().encode(`debateai:audit-source-ip:v1�198.51.100.${round}.${i}`),
        new Uint8Array(32).fill(3), AU);
    }
    return pool.hashPassword(
      new TextEncoder().encode(`r${round}-j${i}`), new Uint8Array(16).fill((i % 250) + 1), PW);
  }));
  await forceGc();
  const memory = process.memoryUsage();
  const stats = pool.stats();
  samples.push({
    round,
    rssMiB: +(memory.rss / 1048576).toFixed(1),
    heapUsedMiB: +(memory.heapUsed / 1048576).toFixed(1),
    externalMiB: +(memory.external / 1048576).toFixed(1)
  });
  restarts.push(stats.restartsInWindow);
}

const rss = samples.map((s) => s.rssMiB);
const firstHalf = rss.slice(0, ROUNDS / 2);
const secondHalf = rss.slice(ROUNDS / 2);
const mean = (xs) => xs.reduce((a, b) => a + b, 0) / xs.length;
const plateau = rss.slice(-4);

console.log(JSON.stringify({
  rounds: ROUNDS,
  jobsPerRound: PER_ROUND,
  totalJobs: ROUNDS * PER_ROUND,
  rssMiB: rss,
  heapUsedMiB: samples.map((s) => s.heapUsedMiB),
  firstHalfMeanRssMiB: +mean(firstHalf).toFixed(1),
  secondHalfMeanRssMiB: +mean(secondHalf).toFixed(1),
  driftMiB: +(mean(secondHalf) - mean(firstHalf)).toFixed(1),
  plateauSpreadMiB: +(Math.max(...plateau) - Math.min(...plateau)).toFixed(3),
  maxRssMiB: Math.max(...rss),
  workerRestartsInWindow: restarts[restarts.length - 1],
  finalStats: pool.stats()
}, null, 2));

await pool.close();

